import{c as e,Q as s,j as n,m as p}from"./chunks/framework.DOi4mjdC.js";const t="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%81%E7%A8%8B.2K4MQ3C5.png",u=JSON.parse('{"title":"DataTypeForBinQuery","description":"","frontmatter":{},"headers":[{"level":1,"title":"DataTypeForBinQuery","slug":"datatypeforbinquery"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpParamDef/DataTypeForBinQuery.md","filePath":"api/Utils-API/原型注册与管理/OpParamDef/DataTypeForBinQuery.md"}'),T={name:"api/Utils-API/原型注册与管理/OpParamDef/DataTypeForBinQuery.md"};function l(i,a,D,r,o,g){return s(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="datatypeforbinquery" tabindex="-1">DataTypeForBinQuery <a class="header-anchor" href="#datatypeforbinquery" aria-label="Permalink to &quot;DataTypeForBinQuery&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置Input/Output用于运行时算子二进制查找的数据类型，和<a href="./DataType.html">DataType</a>/<a href="./DataTypeList.html">DataTypeList</a>的数量一致，且一一对应。</p><p>算子编译过程中，会根据数据类型生成多个.o，并通过这些数据类型在运行时索引算子二进制。某些算子支持多种数据类型，且对数据类型不敏感，这时可以使用该接口，将多种数据类型映射到同一个算子二进制，多个数据类型可以复用一个.o，从而减少二进制文件的生成。</p><p>例如，如果一个算子的输入支持多种数据类型（ge::DT_INT16 和ge::DT_INT32），并且使用ge::DT_INT16 输入时可以复用ge::DT_INT32 的二进制文件而不影响最终结果，那么可以采用如下配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>    .ParamType(REQUIRED)</span></span>
<span class="line"><span>    .DataType({ge::DT_INT16, ge::DT_INT32})</span></span>
<span class="line"><span>    .DataTypeForBinQuery({ge::DT_INT32, ge::DT_INT32})</span></span>
<span class="line"><span>    .Format({ge::FORMAT_ND, ge::FORMAT_ND});</span></span></code></pre></div><p>这样，只需生成一个目标文件（.o），就能实现对多种数据类型的支持。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;DataTypeForBinQuery(std::vector&lt;ge::DataType&gt; types)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>types</td><td>输入</td><td>算子参数数据类型。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="./OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>DataTypeForBinQuery的参数个数需要和当前算子参数的DataType或者DataTypeList的参数个数保持一致。</p></li><li><p>不支持与<a href="./To.html">To</a>（指定数据类型）的接口同时使用。</p></li><li><p>需要保证使用DataTypeForBinQuery后，产生新的算子参数属性集合（使用DataTypeForBinQuery替换原本DataType序列）存在于原本支持的参数属性集合中。</p><p>参数属性集合的定义为，算子所支持的所有参数的属性的集合，相当于一列参数的集合。</p><p>例如<a href="#li26512368417">示例一</a>中。算子支持四种原集合，没有重复。</p><p>1、x : DT_FLOAT16, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>2、x : DT_FLOAT, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>3、x : DT_INT16, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>4、x : DT_INT32, FORMAT_ND y : DT_INT16, FORMAT_NC</p><p>使用DataTypeForBinQuery替换原本DataType序列后，新集合为</p><p>1、x : DT_INT16, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>2、x : DT_FLOAT16, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>3、x : DT_FLOAT16, FORMAT_ND y : DT_INT16, FORMAT_ND</p><p>4、x : DT_INT16, FORMAT_ND y : DT_INT16, FORMAT_NC</p><p>此时发现，新集合1与原集合3一致，新集合2、新集合3与原集合1一致。设置生效。新集合4不属于原集合，设置失效。此时会按照原本的集合4进行编译。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>示例一</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT16, ge::DT_INT32})</span></span>
<span class="line"><span>            .DataTypeForBinQuery({ge::DT_INT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_INT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_INT16, ge::DT_INT16, ge::DT_INT16, ge::DT_INT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_NC});</span></span></code></pre></div><p>如下图所示，没有设置DataTypeForBinQuery之前，会生成4个二进制。通过上述代码设置DataTypeForBinQuery后：</p><ul><li>替换后第1列使用原来第3列的二进制，第2列和第3列使用原来第1列的二进制。第4列仍使用第4列的二进制。</li><li>替换后，第2列和第3列完全一致，达成二进制复用的效果，算子总二进制会由原来的四个（bin1，bin2，bin3，bin4）缩减至现在的三个（bin1，bin3、bin4）。</li></ul><p><img src="`+t+`" alt=""></p></li><li><p>示例二</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 简单用例，此时会有两对复用，1、2列-&gt;1列，3、4列-&gt;4列。总共生成1、4两个二进制。所有支持的DataType会传入这两个二进制运行。</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT16, ge::DT_INT32})</span></span>
<span class="line"><span>            .DataTypeForBinQuery({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_INT32, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span></code></pre></div></li><li><p>示例三</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 复杂用例，可以多个Input/Output同时使用DataTypeForBinQuery，此时也会产生两对复用。1、2列-&gt;2列，3、4列-&gt;1列。总共生成1、2两个二进制。所有支持的DataType会传入这两个二进制运行。</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT16, ge::DT_INT32})</span></span>
<span class="line"><span>            .DataTypeForBinQuery({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32, ge::DT_INT16})</span></span>
<span class="line"><span>            .DataTypeForBinQuery({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32, ge::DT_INT16})</span></span>
<span class="line"><span>            .DataTypeForBinQuery({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span></code></pre></div></li></ul>`,17)])])}const F=e(T,[["render",l]]);export{u as __pageData,F as default};
